type MetadataClient interface {
	MetadataRevised(request *MetadataRevisedNotificationType) error

	MetadataRevisedContext(ctx context.Context, request *MetadataRevisedNotificationType) error
}

type metadataClient struct {
	client *soap.Client
}

func NewMetadataClient(client *soap.Client) MetadataClient {
	return &metadataClient{
		client: client,
	}
}

func (service *metadataClient) MetadataRevisedContext(ctx context.Context, request *MetadataRevisedNotificationType) error {

	err := service.client.CallContext(ctx, "''", request, struct{}{})
	if err != nil {
		return err
	}

	return nil
}

func (service *metadataClient) MetadataRevised(request *MetadataRevisedNotificationType) error {
	return service.MetadataRevisedContext(
		context.Background(),
		request,
	)
}
